#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

int numMusicPlaylists(int n, int goal, int k) {
    long long *dp = (long long *)calloc((size_t)(n + 1), sizeof(long long));
    if (!dp) return 0;
    dp[0] = 1;
    for (int length = 1; length <= goal; ++length) {
        for (int used = n; used >= 1; --used) {
            long long newSong = dp[used - 1] * (n - used + 1LL);
            long long repeatSong = dp[used] * (used - k > 0 ? used - k : 0);
            dp[used] = (newSong + repeatSong) % MOD;
        }
        dp[0] = 0;
    }
    int ans = (int)dp[n];
    free(dp);
    return ans;
}

